        {
          "label": "A",
          "text": "Fairness"
        },
        {
          "label": "B",
          "text": "Explainability"
        },
        {
          "label": "C",
          "text": "Privacy and security"
        },
        {
          "label": "D",
          "text": "Transparency"
        }
